parameters.value:
{
  "embeds": [
    {
      "title": "🚨 SOC ALERT: High Severity Intrusion Detected",
      "color": 15158332,
      "fields": [
        { "name": "Rule ID", "value": "$exec.all_fields.rule.id", "inline": true },
        { "name": "Severity Level", "value": "$exec.all_fields.rule.level", "inline": true },
        { "name": "Attacker IP", "value": "$exec.all_fields.full_log.src_ip", "inline": true },
        { "name": "Target Host", "value": "$exec.all_fields.agent.name", "inline": true },
        { "name": "Description", "value": "$exec.all_fields.rule.description" },
        { "name": "VirusTotal Malicious Score", "value": "$virustotal_v3_1.body.data.attributes.last_analysis_stats.malicious" }
      ],
      "footer": { "text": "Wazuh + Shuffle SOAR Automated Response" }
    }
  ]
}
